// CloudIT Operations Portal — Phase 6 endpoint evidence collector.
//
// Computes the shared run-time constants. Run Once for Each Item: returns the
// JSON for one item directly. All timestamps are computed at RUN TIME — never
// hardcode a test clock: publishedAt must be within ±5 minutes of ingestion
// (0004 stale_timestamp).
//
// `observations` seeds the accumulator that each Observe node appends to and
// re-reads from the PREVIOUS Observe node (never from an HTTP output — n8n
// HTTP nodes do not pass input fields through).

const now = new Date();
const nowMs = now.getTime();
const BUCKET_MS = 5 * 60 * 1000; // five-minute idempotency bucket
const bucketStart = new Date(Math.floor(nowMs / BUCKET_MS) * BUCKET_MS);
const pad = (n) => String(n).padStart(2, '0');
// UTC bucket label, e.g. 2026-09-12T0945 — opaque; only uniqueness matters.
const bucket =
  bucketStart.getUTCFullYear() + '-' + pad(bucketStart.getUTCMonth() + 1) + '-' +
  pad(bucketStart.getUTCDate()) + 'T' + pad(bucketStart.getUTCHours()) + pad(bucketStart.getUTCMinutes());

return {
  observedAt: now.toISOString(),
  publishedAt: now.toISOString(),
  freshUntil: new Date(nowMs + 1200 * 1000).toISOString(), // seeded 20-minute freshness
  bucket,
  observations: []
};

// Wall-clock start for the responseTimeMs of the Check that follows; read
// back by the Observe node after the HTTP request.
return { t0: Date.now() };

// Builds the cavetta.website observation and appends it to the accumulator
// that flows through the Observe nodes.
//
// The HTTP output ($json) carries ONLY the check result — n8n HTTP nodes do
// not pass input fields through on either output (success or error) — so:
//   - the endpoint key is hardcoded (no dependence on input passthrough),
//   - the wall-clock start comes from the T0 Website node,
//   - the accumulated state (timestamps + prior observations) is re-read from
//     the Prepare Checks node, NEVER from the HTTP output.
// Fully sequential, single-shot execution makes these references reliable.
//
// "Include Response Data" is ON, so a SUCCESS item is
// { body, headers, statusCode, statusMessage }. A FAILED check arrives as
// { error: ... } which may carry error.statusCode for HTTP-level rejections
// but never for network/timeout errors — anything that is not a confirmed 2xx
// status counts as unavailable.

const http = $json;
const t0Node = $('T0 Website').first().json;
const prev = $('Prepare Checks').first().json;

const err = http && typeof http.error === 'object' && http.error ? http.error : {};
const candidates = [http.statusCode, err.statusCode, http.details && http.details.statusCode];
let status = null;
for (const c of candidates) {
  const n = typeof c === 'string' ? parseInt(c, 10) : c;
  if (Number.isInteger(n) && n >= 100 && n <= 599) { status = n; break; }
}

const observation = {
  endpointKey: 'cavetta.website',
  available: status !== null && status >= 200 && status <= 299,
  httpStatus: status,
  httpStatusClass: status === null ? null : Math.floor(status / 100),
  // Wall-clock through the T0 -> HTTP -> Observe chain; APPROXIMATE latency.
  responseTimeMs: Number.isInteger(t0Node.t0) ? Math.max(0, Math.min(120000, Math.round(Date.now() - t0Node.t0))) : null,
  checkedAt: new Date().toISOString()
};

return {
  observedAt: prev.observedAt,
  publishedAt: prev.publishedAt,
  freshUntil: prev.freshUntil,
  bucket: prev.bucket,
  observations: [...(Array.isArray(prev.observations) ? prev.observations : []), observation]
};

// Wall-clock start for the responseTimeMs of the Check that follows; read
// back by the Observe node after the HTTP request.
return { t0: Date.now() };

