return {
  observedAt: prev.observedAt,
  publishedAt: prev.publishedAt,
  freshUntil: prev.freshUntil,
  bucket: prev.bucket,
  observations: [...(Array.isArray(prev.observations) ? prev.observations : []), observation]
};

// Assembles ONE publish batch of five endpoint_observation envelopes from
// the accumulator left by Observe Public API.
//
// Payload keys are the strict allowlist of
// operations_ingest.insert_endpoint_observation (migration 0005): any extra
// key rejects the WHOLE batch with unknown_field. monitorKey and
// tlsDaysRemaining are intentionally omitted (subset is allowed; TLS
// inspection is a follow-up per the Phase 6 design). confirmationState is
// "unconfirmed": this collector does not do the two-minute recheck —
// confirmed outages continue to come from the Incident Monitor (Phase 0 11.2).
//
// DEFENSIVE: required payload fields are coerced so they can never be
// undefined (undefined = a silent missing_field 422 from the ingest service).
// An uncheckable observation degrades to available:false / null fields, never
// to a rejected batch.

const acc = $('Observe Public API').first().json;
const observations = Array.isArray(acc.observations) ? acc.observations : [];

const records = observations.map((o) => ({
  contractVersion: '1.0',
  recordType: 'endpoint_observation',
  idempotencyKey: 'endpoint-' + (o.endpointKey || 'unknown') + '-' + acc.bucket,
  environmentKey: 'production',
  sourceSystem: 'n8n',
  observedAt: acc.observedAt,
  publishedAt: acc.publishedAt,
  freshUntil: acc.freshUntil,
  status: o.available === true ? 'GREEN' : 'AMBER',
  severity: o.available === true ? 'none' : 'warning',
  correlationKey: null,
  payload: {
    endpointKey: o.endpointKey || 'unknown',
    checkedAt: o.checkedAt || acc.observedAt,
    available: o.available === true,
    httpStatusClass: o.httpStatusClass != null ? o.httpStatusClass : null,
    httpStatus: o.httpStatus != null ? o.httpStatus : null,
    responseTimeMs: Number.isInteger(o.responseTimeMs) ? o.responseTimeMs : null,
    confirmationState: 'unconfirmed'
  }
}));

// NOTE (owner): if you re-select the sub-workflow in the Publish Evidence
// node and n8n wipes the two workflow inputs, re-enter them:
//   records      = {{ JSON.stringify($json.records) }}   (Allow Any Type)
//   publisherKey = {{ $json.publisherKey }}              (String)
// Keep Attempt To Convert Types ON. Mustache only — never a leading '='.

return { records, publisherKey: 'cavetta-production-n8n' };

// Fails LOUDLY (a descriptive Error, visible in the n8n run, no secrets)
// instead of letting the ingest service reject the batch with a cryptic 422.
// Catches exactly the failure mode seen in the first live test: records
// arriving with undefined payload fields.

const records = $json.records;
const REQUIRED_ENVELOPE = ['contractVersion', 'recordType', 'idempotencyKey', 'environmentKey', 'sourceSystem', 'observedAt', 'publishedAt', 'freshUntil', 'status', 'severity'];
const REQUIRED_PAYLOAD = ['endpointKey', 'checkedAt', 'available', 'confirmationState'];

if (!Array.isArray(records) || records.length !== 5) {
  throw new Error('Validate Records: expected exactly 5 endpoint_observation records, got ' + (Array.isArray(records) ? records.length : typeof records));
}

for (let i = 0; i < records.length; i++) {
  const r = records[i];
  for (const k of REQUIRED_ENVELOPE) {
    if (r[k] === undefined || r[k] === null) {
      throw new Error('Validate Records: record ' + i + ' (endpointKey ' + (r.payload && r.payload.endpointKey) + ') is missing envelope field "' + k + '"');
    }
  }
  if (typeof r.payload !== 'object' || r.payload === null) {
    throw new Error('Validate Records: record ' + i + ' has no payload object');
  }
  for (const k of REQUIRED_PAYLOAD) {
    if (r.payload[k] === undefined || r.payload[k] === null) {
      throw new Error('Validate Records: record ' + i + ' (' + r.payload.endpointKey + ') is missing payload field "' + k + '"');
    }
  }
  if (typeof r.payload.available !== 'boolean') {
    throw new Error('Validate Records: record ' + i + ' (' + r.payload.endpointKey + ') has a non-boolean "available"');
  }
  if (r.idempotencyKey.length > 160 || r.idempotencyKey.includes('@') || r.idempotencyKey.includes('://')) {
    throw new Error('Validate Records: record ' + i + ' (' + r.payload.endpointKey + ') has an illegal idempotencyKey "' + r.idempotencyKey + '"');
  }
}

return $json;
